import numpy as np
import biotite.structure as struc
from biotite.structure import Atom, AtomArray
from biotite.structure.bonds import connect_via_residue_names, BondType

# Build a 3-residue peptide where the MIDDLE residue has altloc A and B
# on ALL atoms (including connector C and N). Use a custom bond dict so we
# do not depend on the Chemical Component Dictionary.
def atom(name, rid, coord):
    return Atom(coord=coord, res_id=rid, res_name='ALA', atom_name=name, element=name[0])

a = AtomArray(0)
# residue 1 (single conf): N CA C O
for nm,c in [('N',[0,0,0]),('CA',[1,0,0]),('C',[2,0,0]),('O',[2,1,0])]:
    a += atom(nm,1,c)
# residue 2 (altloc A and B on every atom)
for alt in ('A','B'):
    off = 0.0 if alt=='A' else 5.0
    for nm,c in [('N',[3,0,off]),('CA',[4,0,off]),('C',[5,0,off]),('O',[5,1,off]),('CB',[4,1,off])]:
        a += atom(nm,2,c)
# residue 3 (single conf)
for nm,c in [('N',[6,0,0]),('CA',[7,0,0]),('C',[8,0,0]),('O',[8,1,0])]:
    a += atom(nm,3,c)

cbd = {'ALA': {
    ('N','CA'):BondType.SINGLE,('CA','C'):BondType.SINGLE,('C','O'):BondType.DOUBLE,
    ('CA','CB'):BondType.SINGLE,('C','N'):BondType.SINGLE,  # intra includes C-N? no, that's inter
}}
# remove intra C-N (peptide is inter-residue)
cbd = {'ALA': {('N','CA'):BondType.SINGLE,('CA','C'):BondType.SINGLE,('C','O'):BondType.DOUBLE,('CA','CB'):BondType.SINGLE}}

bl = connect_via_residue_names(a, custom_bond_dict=cbd)
ba = bl.as_array()
print('total atoms:', a.array_length(), 'bonds:', len(ba))
# peptide bonds: between C of res i and N of res i+1
def idx(rid, name, which=0):
    m = (a.res_id==rid)&(a.atom_name==name)
    return np.where(m)[0]
# res1 C -> res2 N(A), N(B); res2 C(A),C(B) -> res3 N
peptide = []
for (i,j) in [(idx(1,'C')[0], idx(2,'N')), (idx(2,'C'), idx(3,'N')[0])]:
    if np.isscalar(i) or hasattr(i,'__len__') and not isinstance(i,np.integer):
        iarr = np.atleast_1d(i); jarr=np.atleast_1d(j)
    else:
        iarr=[i]; jarr=[j]
    for ii in np.atleast_1d(i):
        for jj in np.atleast_1d(j):
            peptide.append((int(ii),int(jj)))
present = set(map(tuple, np.sort(ba[:,:2],axis=1).tolist()))
print('expected peptide bonds:', peptide)
for p in peptide:
    sp = tuple(sorted(p))
    print('  bond', sp, 'present:', sp in present)
